/* ---------------- health reminders ---------------- */
function autosize(ta){
  if(!ta) return;
  ta.style.height = "auto";
  ta.style.height = (ta.scrollHeight + 2) + "px";
}

function renderReminders(){
  var host = document.getElementById("remList");
  var list = state.reminders || [];
  host.innerHTML = "";
  if(!list.length){
    var li = document.createElement("li");
    li.className = "remempty";
    li.style.gridColumn = "1 / -1";
    li.textContent = "Nothing here yet.";
    host.appendChild(li);
    return;
  }
  list.forEach(function(r){
    var li = document.createElement("li");
    li.dataset.id = r.id;
    li.innerHTML = '<span class="rdot"></span>' +
      '<textarea data-act="remtext" rows="1" aria-label="Reminder">' + esc(r.text) + '</textarea>' +
      '<button class="del" data-act="remdel" title="Remove reminder" aria-label="Remove reminder">\\u00d7</button>';
    host.appendChild(li);
    autosize(li.querySelector("textarea"));
  });
}

function addReminder(){
  var input = document.getElementById("remInput");
  var text = input.value.replace(/\\s+$/, "");
  if(!text.trim()) return;
  mark();
  if(!state.reminders) state.reminders = [];
  state.reminders.push({id:uid(), text:text});
  input.value = "";
  autosize(input);
  save(); renderReminders();
  input.focus();
}
document.getElementById("remForm").addEventListener("submit", function(e){
  e.preventDefault();
  addReminder();
});
document.getElementById("remInput").addEventListener("input", function(){ autosize(this); });
document.getElementById("remInput").addEventListener("keydown", function(e){
  /* a notepad: Enter breaks the line, the modifier saves */
  if(e.key === "Enter" && (e.metaKey || e.ctrlKey)){ e.preventDefault(); addReminder(); }
});

document.getElementById("remList").addEventListener("input", function(e){
  if(e.target.dataset.act !== "remtext") return;
  var li = e.target.closest("li");
  var r = (state.reminders || []).filter(function(x){ return x.id === li.dataset.id; })[0];
  if(!r) return;
  markTyping("rem:" + r.id);
  r.text = e.target.value;
  autosize(e.target);
  save();
});

document.getElementById("remList").addEventListener("click", function(e){
  var b = e.target.closest("[data-act=remdel]");
  if(!b) return;
  var li = b.closest("li");
  mark();
  state.reminders = (state.reminders || []).filter(function(x){ return x.id !== li.dataset.id; });
  save(); renderReminders();
  toast("Reminder removed \\u2014 Undo restores it");
});

/* ---------------- date tooltip ---------------- */
var tipEl = document.createElement("div");
tipEl.className = "tip";
tipEl.setAttribute("aria-hidden", "true");
document.body.appendChild(tipEl);
var tipTimer = null;

function tipFill(g){
  tipEl.innerHTML =
    '<b>' + esc(g.dataset.tipLabel || "") + '</b>' +
    '<span class="tip-date">' + esc(g.dataset.tipDate || "") + '</span>' +
    (g.dataset.tipMeta ? '<span class="tip-meta">' + esc(g.dataset.tipMeta) + '</span>' : '');
}
function tipAtPointer(g, x, y){
  tipFill(g);
  tipEl.classList.remove("pinned");
  tipEl.classList.add("on");
  var r = tipEl.getBoundingClientRect();
  var left = Math.min(Math.max(8, x + 14), window.innerWidth - r.width - 8);
  var top = y - r.height - 14;
  if(top < 8) top = y + 20;
  tipEl.style.left = left + "px";
  tipEl.style.top = top + "px";
}
/* touch has no hover, so a tap parks the date at the bottom of the screen
   where it stays readable while the page scrolls to the step */
function tipPin(g){
  tipFill(g);
  tipEl.style.left = "";
  tipEl.style.top = "";
  tipEl.dataset.forId = g.dataset.id;
  tipEl.classList.add("pinned", "on");
  clearTimeout(tipTimer);
}
function tipHide(){
  tipEl.classList.remove("on");
  delete tipEl.dataset.forId;
}
function tipIsOpenFor(g){
  return tipEl.classList.contains("on") && tipEl.dataset.forId === g.dataset.id;
}


/* ---------------- drag a task to reorder ----------------
   Mouse: press the grip (or blank space in a row) and move.
   Touch: hold for a moment, then move. Dropping only changes the ORDER;
   no date moves until you type one in yourself. */
(function(){
  var agenda = document.getElementById("agenda");
  var press = null, drag = null;

  function rowsNow(){
    return Array.prototype.slice.call(agenda.querySelectorAll(".row"));
  }

  function begin(){
    if(!press || drag) return;
    var row = press.row;
    drag = {row:row, id:row.dataset.id, line:document.createElement("div")};
    drag.line.className = "drop-line";
    row.classList.add("dragging");
    row.parentNode.insertBefore(drag.line, row.nextSibling);
    document.body.classList.add("dragging-active");
    press.started = true;
  }

  function placeLine(y){
    var rows = rowsNow().filter(function(r){ return r !== drag.row; });
    var i, rect;
    for(i = 0; i < rows.length; i++){
      rect = rows[i].getBoundingClientRect();
      if(y < rect.top + rect.height / 2){
        rows[i].parentNode.insertBefore(drag.line, rows[i]);
        return;
      }
    }
    if(rows.length){
      var last = rows[rows.length-1];
      last.parentNode.insertBefore(drag.line, last.nextSibling);
    }
  }

  function edgeScroll(y){
    var margin = 80;
    if(y < margin) window.scrollBy(0, -14);
    else if(y > window.innerHeight - margin) window.scrollBy(0, 14);
  }

  function finish(){
    if(!drag){ press = null; return; }
    var c = cur();
    /* read the order straight off the page, with the line standing in for the row */
    var order = [], kids = Array.prototype.slice.call(agenda.children);
    kids.forEach(function(el){
      if(el === drag.line) order.push(drag.id);
      else if(el.classList && el.classList.contains("row") && el !== drag.row) order.push(el.dataset.id);
    });
    if(order.indexOf(drag.id) === -1) order.push(drag.id);

    var map = {};
    c.steps.forEach(function(s){ map[s.id] = s; });
    var next = [];
    order.forEach(function(id){ if(map[id]){ next.push(map[id]); delete map[id]; } });
    c.steps.forEach(function(s){ if(map[s.id]) next.push(s); });

    var movedStep = null;
    c.steps.forEach(function(s){ if(s.id === drag.id) movedStep = s; });

    if(drag.line.parentNode) drag.line.parentNode.removeChild(drag.line);
    drag.row.classList.remove("dragging");
    document.body.classList.remove("dragging-active");
    var sameOrder = next.length === c.steps.length &&
                    next.every(function(s, i){ return s === c.steps[i]; });
    drag = null; press = null;

    if(sameOrder) return;              /* dropped back where it started */
    mark();
    c.steps = next;
    if(movedStep && !movedStep.pending) movedStep.moved = true;
    normalize(c);
    save(); render();
    toast("Moved — set its date to confirm");
  }

  agenda.addEventListener("pointerdown", function(e){
    if(e.button != null && e.button !== 0) return;
    var onGrip = e.target.closest && e.target.closest("[data-act=grip]");
    if(!onGrip && e.target.closest("input, textarea, button, select, label, a")) return;
    var row = e.target.closest(".row");
    if(!row) return;
    if(isDueStep(stepById(cur(), row.dataset.id))) return;
    press = {row:row, x:e.clientX, y:e.clientY, touch:e.pointerType === "touch",
             started:false, timer:null};
    if(press.touch && !onGrip){
      press.timer = setTimeout(begin, 420);        /* long press */
    }else if(onGrip){
      begin();                                     /* the grip means business */
      placeLine(e.clientY);
    }
  });

  window.addEventListener("pointermove", function(e){
    if(!press) return;
    if(!drag){
      var dx = Math.abs(e.clientX - press.x), dy = Math.abs(e.clientY - press.y);
      if(press.touch){
        if(dx + dy > 12){ clearTimeout(press.timer); press = null; }   /* a scroll */
        return;
      }
      if(dx + dy > 4) begin(); else return;
    }
    placeLine(e.clientY);
    edgeScroll(e.clientY);
  });

  window.addEventListener("pointerup", function(){
    if(press && press.timer) clearTimeout(press.timer);
    if(drag) finish(); else press = null;
  });
  window.addEventListener("pointercancel", function(){
    if(press && press.timer) clearTimeout(press.timer);
    if(drag) finish(); else press = null;
  });

  /* stop the page scrolling under a touch drag */
  window.addEventListener("touchmove", function(e){
    if(drag) e.preventDefault();
  }, {passive:false});
})();

/* ---------------- chart -> list jump ---------------- */
function jumpToStep(id){
  var row = document.querySelector('.row[data-id="' + id + '"]');
  if(!row) return;
  var reduce = window.matchMedia &&
               window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  /* after the click settles, so the browser's own focus-scroll cannot fight it.
     A timer rather than rAF: rAF is suspended while a tab is in the background. */
  setTimeout(function(){
    try{
      row.scrollIntoView({behavior: reduce ? "auto" : "smooth", block: "center"});
    }catch(e){ row.scrollIntoView(); }
  }, 0);
  row.classList.remove("flash");
  void row.offsetWidth;              /* restart the flash if the same bar is tapped twice */
  row.classList.add("flash");
  setTimeout(function(){ row.classList.remove("flash"); }, 1700);
}
(function(){
  var rows = document.getElementById("rows");
  /* These rows carry tabindex, so a plain click focuses them and the browser scrolls the
     CHART back into view, undoing our jump. Take focus ourselves without that scroll. */
  rows.addEventListener("mousedown", function(e){
    var g = e.target.closest ? e.target.closest(".grow") : null;
    if(!g) return;
    e.preventDefault();
    try{ g.focus({preventScroll:true}); }catch(err){ g.focus(); }
  });
  var lastPointer = "mouse";
  rows.addEventListener("pointerdown", function(e){ lastPointer = e.pointerType || "mouse"; });
  rows.addEventListener("pointerover", function(e){
    if(e.pointerType && e.pointerType !== "mouse") return;
    var g = e.target.closest ? e.target.closest(".grow") : null;
    if(g) tipAtPointer(g, e.clientX, e.clientY);
  });
  rows.addEventListener("pointermove", function(e){
    if(e.pointerType && e.pointerType !== "mouse") return;
    var g = e.target.closest ? e.target.closest(".grow") : null;
    if(g) tipAtPointer(g, e.clientX, e.clientY); else tipHide();
  });
  rows.addEventListener("pointerleave", tipHide);
  rows.addEventListener("click", function(e){
    var g = e.target.closest ? e.target.closest(".grow") : null;
    if(!g) return;
    if(lastPointer === "mouse"){
      tipHide();
      jumpToStep(g.dataset.id);
      return;
    }
    /* Touch has no hover, so the row is split: the bar answers "when is this?",
       the name answers "take me to it". */
    if(e.target.closest(".glab")){
      tipHide();
      jumpToStep(g.dataset.id);
    }else if(tipIsOpenFor(g)){
      tipHide();                    /* second tap on the same bar closes it */
    }else{
      tipPin(g);
    }
  });
  /* tapping anywhere else puts the card away */
  document.addEventListener("click", function(e){
    if(!tipEl.classList.contains("pinned")) return;
    if(e.target.closest && e.target.closest("#rows")) return;
    tipHide();
  });
  rows.addEventListener("keydown", function(e){
    if(e.key !== "Enter" && e.key !== " " && e.key !== "Spacebar") return;
    var g = e.target.closest ? e.target.closest(".grow") : null;
    if(!g) return;
    e.preventDefault();
    jumpToStep(g.dataset.id);
  });
})();


