/* ---------------- history ---------------- */
(function(){
  var sheet = document.getElementById("histSheet");
  var list = document.getElementById("histList");

  function when(iso){
    var d = new Date(iso);
    var h = d.getHours(), m = d.getMinutes();
    return (h % 12 || 12) + ":" + (m < 10 ? "0" : "") + m + (h < 12 ? "am" : "pm");
  }
  function dayLabel(iso){
    var d = new Date(iso), t = parseISO(todayISO());
    var days = diffDays(new Date(d.getFullYear(), d.getMonth(), d.getDate()), t);
    if(days === 0) return "Today";
    if(days === -1) return "Yesterday";
    return WD[d.getDay()] + ", " + fmtShort(d);
  }
  /* say what actually changed between one restore point and the next */
  function describe(e, newer){
    var bits = [];
    if(newer){
      if(e.steps !== newer.steps){
        var n = newer.steps - e.steps;
        bits.push(n > 0 ? "<b>" + plural(n, "step") + " added</b>"
                        : "<b>" + plural(-n, "step") + " removed</b>");
      }
      if(e.day1 !== newer.day1) bits.push("<b>Day 1 changed</b>");
      if(e.title !== newer.title) bits.push("<b>renamed</b>");
    }
    if(!bits.length) bits.push("edits");
    return bits.join(" \\u00b7 ") + " \\u00b7 " + e.steps + " steps";
  }

  function renderHistory(entries){
    list.innerHTML = "";
    if(!entries.length){
      list.innerHTML = '<div class="histempty">No restore points yet. They start appearing ' +
        'as soon as edits are made.</div>';
      return;
    }
    var lastDay = null;
    entries.forEach(function(e, i){
      var d = dayLabel(e.t);
      if(d !== lastDay){
        lastDay = d;
        var h = document.createElement("div");
        h.className = "histday";
        h.textContent = d;
        list.appendChild(h);
      }
      var row = document.createElement("div");
      row.className = "histrow";
      row.innerHTML =
        '<div class="histtime">' + when(e.t) + '</div>' +
        '<div class="histwhat">' + describe(e, entries[i-1]) +
          '<span class="histwho">' +
          (e.by_id === clientId ? "this device" : "another device") + '</span></div>' +
        '<button class="btn" data-restore="' + e.id + '">Restore</button>';
      list.appendChild(row);
    });
  }

  function load(){
    list.innerHTML = '<div class="histempty">Loading\\u2026</div>';
    fetch("api/history", {cache:"no-store"})
      .then(function(r){ if(!r.ok) throw 0; return r.json(); })
      .then(function(res){ renderHistory(res.entries || []); })
      .catch(function(){
        list.innerHTML = '<div class="histempty">Could not reach the server. ' +
          'Check the connection and press Refresh.</div>';
      });
  }

  list.addEventListener("click", function(e){
    var b = e.target.closest("[data-restore]");
    if(!b) return;
    if(!confirm("Put the timeline back to this point? Everyone on the link sees the change, " +
                "and the version you are on now is kept so you can come back to it.")) return;
    b.disabled = true;
    b.textContent = "Restoring\\u2026";
    fetch("api/history", {
      method:"POST", headers:{"content-type":"application/json"},
      body: JSON.stringify({id: +b.getAttribute("data-restore"), by: clientId})
    }).then(function(r){ if(!r.ok) throw 0; return r.json(); })
      .then(function(res){
        lastSeenT = res.t;
        applyRemote(res.d);
        snapshot = null;
        document.getElementById("undoBtn").disabled = true;
        sheet.classList.remove("on");
        toast("Restored");
      })
      .catch(function(){
        b.disabled = false; b.textContent = "Restore";
        toast("Could not restore \\u2014 check the connection");
      });
  });

  document.getElementById("histBtn").addEventListener("click", function(){
    sheet.classList.add("on");
    load();
  });
  document.getElementById("histRefresh").addEventListener("click", load);
  document.getElementById("histClose").addEventListener("click", function(){
    sheet.classList.remove("on");
  });
  sheet.addEventListener("click", function(e){ if(e.target === sheet) sheet.classList.remove("on"); });
  document.addEventListener("keydown", function(e){
    if(e.key === "Escape" && sheet.classList.contains("on")) sheet.classList.remove("on");
  });
})();


