var BUMP_KEY = "bump.due";
var bumpWeek = null;                 /* the week being browsed, null = follow today */

/* the due date the timeline derives from the transfer, via the LMP-equivalent */
function timelineDue(){
  var c = cur(), out = null;
  c.steps.forEach(function(s){
    if(out === null && /DUE DATE/i.test(s.label)) out = iso(addDays(parseISO(c.day1), s.start));
  });
  return out;
}
function bumpDue(){
  return timelineDue() || "";        /* locked: always 39 weeks after the first beta */
}
function bumpSetDue(v){
  /* no-op: due date is locked to the pregnancy test on Timeline */
}
function bumpFollowTimeline(){
  try{ localStorage.removeItem(BUMP_KEY); localStorage.removeItem(BUMP_KEY + ".manual"); }catch(e){}
}
/* Gestation for fruit sizes uses transfer dating (true medical weeks).
   Countdown \`left\` uses the timeline due date (39 weeks from the positive test). */
function bumpToday(){
  var due = bumpDue();
  var today = parseISO(todayISO());
  var lmp = lmpDate();
  var days = diffDays(today, lmp);
  var left = due ? diffDays(parseISO(due), today) : (273 - days);
  return {days:days, week:Math.max(1, Math.min(40, Math.floor(days / 7) || 1)), left:left};
}

function trimesterOf(w){ return w <= 13 ? "First trimester" : (w <= 27 ? "Second trimester" : "Third trimester"); }
function cmToIn(cm){ return Math.round(cm / 2.54 * 10) / 10; }
function gToOz(g){ return Math.round(g / 28.35 * 10) / 10; }
function gToLb(g){
  var lb = Math.floor(g / 453.6), oz = Math.round((g - lb * 453.6) / 28.35);
  if(oz === 16){ lb++; oz = 0; }
  return lb + "lb " + oz + "oz";
}


