function renderZodiac(){
  var due = bumpDue();
  var card = document.getElementById("bStarCard");
  if(!due){ card.hidden = true; return; }
  card.hidden = false;
  var d = parseISO(due);
  var got = zodiacFor(d), z = got.z, i = got.i;

  document.getElementById("bStarGlyph").textContent = z[2];
  document.getElementById("bStarKicker").textContent =
    /^[AEIOU]/.test(z[4]) ? "Probably an" : "Probably a";
  document.getElementById("bStarName").innerHTML =
    esc(z[4]) + ' <span id="bStarEmoji">' + z[3] + "</span>";
  var nxt = ZODIAC[(i + 1) % 12];
  document.getElementById("bStarDates").textContent =
    MON[z[0]-1] + " " + z[1] + " – " + MON[nxt[0]-1] + " " + (nxt[1]-1) + "  ·  " + z[5];
  document.getElementById("bStarTraits").textContent = "Reportedly " + z[6] + ".";

  /* a due date is a guess, so say what an early or late arrival would mean */
  var y = d.getFullYear();
  var nextStart = signStart((i + 1) % 12, (i === 11) ? y + 1 : y);
  var thisStart = signStart(i, (i === 11 && d.getMonth() === 0) ? y - 1 : y);
  var toNext = diffDays(nextStart, d);
  var sincePrev = diffDays(d, thisStart);
  var prev = ZODIAC[(i + 11) % 12];
  var msg = "";
  if(toNext <= 6) msg = "Cusp alert — arrive " + plural(toNext, "day") + " late and you get " + anSign(nxt[4]) + " " + nxt[3] + " instead.";
  else if(sincePrev <= 6) msg = "Cusp alert — arrive " + plural(sincePrev + 1, "day") + " early and you get " + anSign(prev[4]) + " " + prev[3] + " instead.";
  else msg = "Babies rarely read the calendar, so this could still shift — " + nxt[4] + " " +
             nxt[3] + " starts in " + plural(toNext, "day") + ".";
  document.getElementById("bStarCusp").textContent = msg;
}

function bumpPregConfirmed(){
  var c = cur();
  var i = testIndex(c);
  return i >= 0 && !!c.steps[i].done;
}
function bumpSetPregBanner(){
  var el = document.getElementById("bNotPreg");
  if(!el) return;
  var waiting = !bumpPregConfirmed();
  el.classList.toggle("is-on", waiting);
  el.hidden = !waiting;
}

function renderBump(){
  /* boot calls render() before this file's data is assigned, so bail out until it is */
  if(typeof BUMP === "undefined" || !document.getElementById("bumpMain")) return;
  bumpSetPregBanner();
  var due = bumpDue();
  var setup = document.getElementById("bumpSetup");
  var main = document.getElementById("bumpMain");
  if(!due){
    setup.hidden = false; main.hidden = true;
    document.getElementById("bStarCard").hidden = true;
    document.getElementById("bWorldCard").hidden = true;
    /* offer the timeline's own due date as a starting point */
    var guess = null, c = cur();
    c.steps.forEach(function(s){ if(guess === null && /DUE DATE/i.test(s.label)) guess = s.start; });
    var hint = document.getElementById("bumpHint");
    if(guess !== null){
      var gd = addDays(parseISO(c.day1), guess);
      var el = document.getElementById("bumpDue");
      if(!el.value) setDateField(el, fmtInput(gd));
      hint.textContent = "Filled in from your timeline (" + fmtLong(gd) + ", " + gd.getFullYear() +
                         "). Change it if that is not right.";
    }else{
      hint.textContent = "";
    }
    return;
  }
  setup.hidden = true; main.hidden = false;
  renderZodiac();
  renderWorld();

  var now = bumpToday();
  var wk = bumpWeek === null ? now.week : bumpWeek;
  var d = BUMP[wk - 1];
  var emoji = d[1], food = d[2], cm = d[3], g = d[4], facts = d[5];

  document.getElementById("bTrim").textContent = trimesterOf(wk);
  document.getElementById("bWkLabel").textContent = "Week " + wk;
  document.getElementById("bEmoji").textContent = emoji;
  document.getElementById("bSize").textContent = "Your baby is about the size of " + food;
  document.getElementById("bFactsWk").textContent = "\\u00b7 week " + wk;

  var when = document.getElementById("bWhen");
  if(now.days < 0){
    /* the pregnancy clock has not started yet, so this is a look-ahead */
    var tx = null, cc = cur();
    cc.steps.forEach(function(s){
      if(tx === null && /EMBRYO TRANSFER/i.test(s.label)) tx = addDays(parseISO(cc.day1), s.start);
    });
    when.textContent = "Not started yet \\u2014 the clock begins around the transfer" +
      (tx ? " on " + fmtLong(tx) : "") + ", " + plural(-now.days, "day") + " away. Have a look ahead.";
  }else if(bumpWeek === null || bumpWeek === now.week){
    var d7 = now.days % 7;
    when.textContent = "You are " + plural(now.week, "week") + (d7 ? " and " + plural(d7, "day") : "") +
      " along \\u00b7 " + (now.left > 0 ? plural(now.left, "day") + " to go" :
                          (now.left === 0 ? "due today!" : plural(-now.left, "day") + " past the due date"));
  }else{
    var diff = wk - now.week;
    when.textContent = diff > 0 ? "Looking ahead " + plural(diff, "week") + " \\u00b7 you are in week " + now.week
                                : "Looking back " + plural(-diff, "week") + " \\u00b7 you are in week " + now.week;
  }

  document.getElementById("bLen").textContent = cm ? (cm + " cm / " + cmToIn(cm) + " in") : "\\u2014";
  document.getElementById("bWt").textContent  = g ? (g >= 454 ? gToLb(g) : g + " g / " + gToOz(g) + " oz") : "\\u2014";
  document.getElementById("bToGo").textContent = (40 - wk) + (40 - wk === 1 ? " week" : " weeks");

  var pct = Math.round(wk / 40 * 100);
  document.getElementById("bProgFill").style.width = pct + "%";
  /* keep the 22px knob fully inside the bar at both ends */
  document.getElementById("bProgKnob").style.left =
    "calc(" + pct + "% + " + (11 - pct * 0.22).toFixed(2) + "px)";
  document.getElementById("bProgRange").value = String(wk);
  document.getElementById("bProgTxt").textContent = wk + " of 40 weeks \\u00b7 " + Math.round(wk / 40 * 100) + "%";

  var ul = document.getElementById("bFacts");
  ul.innerHTML = "";
  facts.forEach(function(f){
    var li = document.createElement("li");
    li.textContent = f;
    ul.appendChild(li);
  });

  document.getElementById("bDueSrc").textContent =
    "Due " + fmtLong(parseISO(due)) + ", " + parseISO(due).getFullYear() +
    " — locked 39 weeks after the first beta. ";
  document.getElementById("bPick").value = String(wk);
  document.getElementById("bPrev").disabled = wk <= 1;
  document.getElementById("bNext").disabled = wk >= 40;
  document.getElementById("bNow").disabled = (bumpWeek === null || bumpWeek === now.week);
}

(function(){
  var pick = document.getElementById("bPick");
  for(var i = 1; i <= 40; i++){
    var o = document.createElement("option");
    o.value = String(i);
    o.textContent = "Week " + i + "  \\u00b7  " + trimesterOf(i).replace(" trimester", "");
    pick.appendChild(o);
  }
  pick.addEventListener("change", function(){ bumpWeek = +this.value; renderBump(); });

  var range = document.getElementById("bProgRange");
  var track = document.querySelector(".bprog-track");
  range.addEventListener("input", function(){ bumpWeek = +this.value; renderBump(); });
  /* drop the easing while a finger or mouse is down so the knob tracks exactly */
  range.addEventListener("pointerdown", function(){ track.classList.add("dragging"); });
  ["pointerup","pointercancel","blur"].forEach(function(ev){
    range.addEventListener(ev, function(){ track.classList.remove("dragging"); });
  });
  document.getElementById("bPrev").addEventListener("click", function(){
    var n = bumpToday(); bumpWeek = Math.max(1, (bumpWeek === null ? n.week : bumpWeek) - 1); renderBump();
  });
  document.getElementById("bNext").addEventListener("click", function(){
    var n = bumpToday(); bumpWeek = Math.min(40, (bumpWeek === null ? n.week : bumpWeek) + 1); renderBump();
  });
  document.getElementById("bNow").addEventListener("click", function(){ bumpWeek = null; renderBump(); });
  var chg = document.getElementById("bChange");
  if(chg) chg.addEventListener("click", function(){
    toast("Due date is locked \\u2014 39 weeks after Pregnancy test (first beta hCG)");
  });
  document.getElementById("bumpSave").addEventListener("click", function(){
    toast("Due date is locked \\u2014 date the first beta on Timeline and this follows");
  });
  var go = document.getElementById("bGoChart");
  if(go) go.addEventListener("click", function(){ showTab("chart"); });
})();


