/* the hearing milestones, dated off the same LMP-equivalent the timeline uses */
function renderEars(){
  var host = document.getElementById("eMiles");
  if(!host) return;
  var due = null, c = cur();
  c.steps.forEach(function(s){
    if(due === null && /DUE DATE/i.test(s.label)) due = addDays(parseISO(c.day1), s.start);
  });
  if(!due){ host.innerHTML = ""; return; }
  var lmp = lmpDate(c);
  var today = parseISO(todayISO());
  var miles = [
    [18, "Ears in place", "they move to their final position on the head"],
    [24, "Listening starts", "loud sounds get a startle; your voice gets through"],
    [32, "Knows your voice", "and will turn towards it once born"]
  ];
  host.innerHTML = "";
  miles.forEach(function(m){
    var d = addDays(lmp, m[0] * 7);
    var away = diffDays(d, today);
    var el = document.createElement("div");
    el.className = "emile";
    el.innerHTML = "<span>" + m[0] + " weeks</span><b>" + esc(m[1]) + "</b>" +
      "<em>" + fmtLong(d) + ", " + d.getFullYear() +
      (away > 0 ? " \\u00b7 in " + plural(away, "day") : (away === 0 ? " \\u00b7 today" : " \\u00b7 passed")) +
      "</em>";
    el.title = m[2];
    host.appendChild(el);
  });
}

