/* ---- music box ----
   A few melodies are stored as note data and played with a soft synth, so a card
   can be heard as well as read. Only tunes that are public domain AND that can be
   written out accurately are included - a card with no entry here shows no player
   rather than an invented melody. Semitones from middle C, then beats. */
var TUNES = {
  Germany: { name: "Wiegenlied, Brahms (1868)",
             n: [[4,1],[4,1],[7,2],[4,1],[4,1],[7,2],[4,1],[7,1],[12,1],[11,1],[9,2],[9,1],[7,3]] }
};
var mcAudio = null, tunePlaying = null;
function tuneStop(){
  if(tunePlaying){ try{ tunePlaying.forEach(function(o){ o.stop(); }); }catch(e){} tunePlaying = null; }
  var b = document.getElementById("lulPlay");
  if(b) b.textContent = "Play the melody";
}
function tunePlay(key){
  var t = TUNES[key];
  if(!t) return;
  try{
    if(!mcAudio) mcAudio = new (window.AudioContext || window.webkitAudioContext)();
    if(mcAudio.state === "suspended") mcAudio.resume();
  }catch(e){ return; }
  tuneStop();
  var now = mcAudio.currentTime + .06, beat = .42, made = [], at = now;
  t.n.forEach(function(p){
    var f = 261.63 * Math.pow(2, p[0] / 12), dur = p[1] * beat;
    var o = mcAudio.createOscillator(), g = mcAudio.createGain();
    o.type = "triangle"; o.frequency.value = f;
    /* quick attack, long decay - roughly a music box */
    g.gain.setValueAtTime(0.0001, at);
    g.gain.exponentialRampToValueAtTime(.22, at + .015);
    g.gain.exponentialRampToValueAtTime(.0001, at + dur * .95);
    o.connect(g); g.connect(mcAudio.destination);
    o.start(at); o.stop(at + dur);
    made.push(o); at += dur;
  });
  tunePlaying = made;
  var b = document.getElementById("lulPlay");
  if(b) b.textContent = "Stop";
  made[made.length - 1].onended = function(){ tunePlaying = null; tuneStop(); };
}

var lulIx = 0;
function lulFill(i){
  var d = LULLABIES[i];
  if(!d) return;
  lulIx = i;
  document.getElementById("lulFront").innerHTML =
    '<span class="lulflag">' + d.flag + "</span>" +
    '<span class="lulcountry">' + esc(d.c) + "</span>" +
    '<p class="lulsong">' + esc(d.song) + "</p>" +
    (d.native ? '<p class="lulnative">' + esc(d.native) + "</p>" : "") +
    '<p class="lulmean">' + esc(d.mean) + "</p>" +
    '<p class="lulnote">' + esc(d.note) + "</p>" +
    (d.verse
      ? '<div class="lulverse"><p class="lulorig">' + esc(d.verse).replace(/\\n/g, "<br>") + "</p>" +
        (d.roman ? '<p class="lulroman">' + esc(d.roman) + "</p>" : "") +
        '<p class="lulen">' + esc(d.english) + "</p></div>"
      : (d.noVerse ? '<p class="lulnoverse">' + esc(d.noVerse) + "</p>" : "")) +
    '<div class="lulplay">' +
      (TUNES[d.c] ? '<button class="lulbtn" id="lulPlay" type="button">Play the melody</button>' : "") +
      '<a class="lulbtn lulout" href="https://www.youtube.com/results?search_query=' +
        encodeURIComponent(d.song + " " + d.c + " lullaby") +
        '" target="_blank" rel="noopener">Hear it sung \\u2197</a>' +
      (TUNES[d.c] ? '<span class="lulboxnote">' + esc(TUNES[d.c].name) + "</span>" : "") +
    "</div>";
  document.getElementById("lulBack").innerHTML =
    '<span class="lulfacthead">Did you know</span>' +
    '<p class="lulfact">' + esc(d.fact) + "</p>";
  if(typeof tuneStop === "function") tuneStop();
  var pb = document.getElementById("lulPlay");
  if(pb) pb.addEventListener("click", function(e){
    e.stopPropagation();                       /* the card flips on click; this must not */
    if(tunePlaying) tuneStop(); else tunePlay(d.c);
  });
  if(typeof gTo === "function") gTo(i);
  document.getElementById("lulCard").classList.remove("flipped");
  document.getElementById("lulHint").textContent = "Tap the card for a fun fact";
}

(function(){
  var card0 = document.getElementById("lulCard");
  if(!card0) return;
  document.getElementById("lulCount").textContent = LULLABIES.length + " countries";

  var card = document.getElementById("lulCard");
  card.setAttribute("role", "button");
  card.setAttribute("tabindex", "0");
  function flip(){
    var on = card.classList.toggle("flipped");
    document.getElementById("lulHint").textContent = on
      ? "Tap again to go back"
      : "Tap the card for a fun fact";
  }
  card.addEventListener("click", flip);
  card.addEventListener("keydown", function(e){
    if(e.key === "Enter" || e.key === " "){ e.preventDefault(); flip(); }
  });
  document.getElementById("lulSpin").addEventListener("click", function(e){
    e.stopPropagation();
    var j = lulIx;
    while(j === lulIx && LULLABIES.length > 1) j = Math.floor(Math.random() * LULLABIES.length);
    lulFill(j);
  });
  lulFill(Math.floor(Math.random() * LULLABIES.length));   /* a different one each visit */
})();


