const FAMILY_SCHEMA = "your-family/v1";
const FAMILY_MAX_BYTES = 900000;
const OWNER_COOKIE = "cm_owner";

async function famBookCover(title, author) {
  try {
    const q = encodeURIComponent([title, author].filter(Boolean).join(" "));
    const sr = await fetch("https://openlibrary.org/search.json?q=" + q + "&limit=5", {
      headers: { accept: "application/json" }
    });
    if (!sr.ok) return null;
    const data = await sr.json();
    const doc = (data.docs || []).find((d) => d.cover_i) || null;
    if (!doc) return null;
    const coverUrl = "https://covers.openlibrary.org/b/id/" + doc.cover_i + "-L.jpg";
    const ir = await fetch(coverUrl);
    if (!ir.ok) return { coverUrl };
    const buf = await ir.arrayBuffer();
    if (!buf.byteLength || buf.byteLength > 450000) return { coverUrl };
    const bytes = new Uint8Array(buf);
    let bin = "";
    const step = 0x8000;
    for (let i = 0; i < bytes.length; i += step) {
      bin += String.fromCharCode.apply(null, bytes.subarray(i, i + step));
    }
    const mime = (ir.headers.get("content-type") || "image/jpeg").split(";")[0];
    return { coverUrl, coverDataUri: "data:" + mime + ";base64," + btoa(bin) };
  } catch (e) {
    return null;
  }
}

async function isOwner(request, env) {
  if (!env.OWNER_PASSCODE) return true;          // lock not configured yet
  return sameToken(readCookie(request, OWNER_COOKIE), await tokenFor(env.OWNER_PASSCODE));
}

